import requests

def safe_get(url):
    try:
        r = requests.get(url, timeout=30)
        r.raise_for_status()          # HTTPError on 4xx/5xx
        return r.json()
    except requests.exceptions.Timeout:
        print("Server slow hai - timeout")
    except requests.exceptions.ConnectionError:
        print("Internet / server band")
    except requests.exceptions.HTTPError as e:
        print("HTTP error:", e.response.status_code)
    return None

replies = iter([503, 503, 200])        # fake server: fails 2 times, then OK

def call_api():
    return next(replies)

def with_retry(max_tries=4):
    wait = 1
    for attempt in range(1, max_tries + 1):
        status = call_api()
        print(f"try {attempt}: {status}")
        if status < 500:
            return status
        print(f"  {wait}s ruk ke retry")
        wait *= 2                      # 1, 2, 4 ... (exponential backoff)
    return None

print("final:", with_retry())

products = {1: {"name": "Copper Wire", "rate": 850}}

def handle(method, path, body=None):
    parts = path.strip("/").split("/")
    if parts[0] != "products":
        return 404, {"detail": "Not found"}
    if method == "GET" and len(parts) == 1:
        return 200, list(products.values())
    if method == "POST" and len(parts) == 1:
        if not body or "name" not in body:
            return 422, {"detail": "name required"}
        new_id = max(products) + 1
        products[new_id] = body
        return 201, {"id": new_id}
    pid = int(parts[1])
    if pid not in products:
        return 404, {"detail": "Product not found"}
    if method == "GET":
        return 200, products[pid]
    if method == "DELETE":
        del products[pid]
        return 204, None
    return 405, {"detail": "Method not allowed"}

print(handle("POST", "/products", {"name": "PVC Cable", "rate": 420}))
print(handle("POST", "/products", {"rate": 10}))
print(handle("GET", "/products/2"))
print(handle("DELETE", "/products/2"))
print(handle("GET", "/products/2"))

